def tbl(df,title):return {'title':title,'columns':[str(c) for c in df.columns],'rows':df.where(pd.notnull(df),None).values.tolist()}
def picking(scenario='default'):
 rng=np.random.default_rng(260801);n=36;sequence=np.array(['AB']*18+['BA']*18);rng.shuffle(sequence);rows=[];effect=1.5 if scenario=='default' else .35
 for worker in range(n):
  baseline=rng.normal(22,2);individual=effect+rng.normal(0,.45)
  for method in ['A','B']:
   second=(sequence[worker]=='AB' and method=='B')or(sequence[worker]=='BA'and method=='A')
   for trial in range(1,21):rows.append([worker+1,sequence[worker],method,trial,baseline-(individual if method=='B' else 0)-(.2 if second else 0)+rng.normal(0,2.4)])
 raw=pd.DataFrame(rows,columns=['operator','sequence','method','trial','seconds']);means=raw.groupby(['operator','sequence','method']).seconds.mean().unstack('method').reset_index();diff=means.A-means.B;n=len(diff);mean=diff.mean();se=stats.sem(diff);ci=stats.t.interval(.95,n-1,loc=mean,scale=se);test=stats.ttest_rel(means.A,means.B);important=1.;volume=12000
 assert len(raw)==1440 and means.shape[0]==36
 fig,ax=plt.subplots();ax.plot([0,1],np.vstack([means.A,means.B]),alpha=.35,color='#235ACB');ax.scatter([0,1],[means.A.mean(),means.B.mean()],c='#D5542B',s=80,zorder=3);ax.set(xticks=[0,1],xticklabels=['A yöntemi','B yöntemi'],ylabel='Operatör başına 20 işin ortalama süresi · sn',title='Aynı operatörde iki yöntem; eşler korunur')
 fig2,ax2=plt.subplots();ax2.errorbar([mean],[1],xerr=[[mean-ci[0]],[ci[1]-mean]],fmt='o',color='#235ACB',capsize=5);ax2.axvline(0,color='gray',ls='--',label='Fark 0');ax2.axvline(important,color='#D5542B',ls='--',label='Önceden seçilen önemli fark 1 sn');ax2.set(yticks=[],xlabel='A−B ortalama süre farkı · saniye',title='%95 eşli t aralığı');ax2.legend()
 order=means.assign(difference=diff).groupby('sequence').difference.agg(['count','mean','std']).reset_index();decision='Aralığın alt sınırı 1 saniyenin üzerinde; bu sınırlı deneyde önceden seçilen önemli iyileşme eşiği destekleniyor.' if ci[0]>important else 'Aralık önemli iyileşme eşiğinin üstünde kalmıyor; küçük p olsa bile en az 1 saniye kazanç iddiası desteklenmiş sayılmaz.'
 return dict(metrics={'Bağımsız birim / ham satır':f'{n} operatör / {len(raw)} iş','A−B farkı · sn':mean,'Alt %95 sınır · sn':ci[0],'Üst %95 sınır · sn':ci[1],'İki yönlü p':test.pvalue,'12.000 işte eşdeğer süre · saat':volume*mean/3600},tables=[tbl(order,'Sıra etkisi için ilk kontrol')],figures=[('Her çizgi aynı operatörün A ve B ortalamalarını bağlar.',fig),('Sıfır ve önceden belirlenen 1 saniyelik iş eşiği ayrı okunur.',fig2)],frames={'ham_isler':raw,'operator_ortalamalari':means},steps=[f'Her operatör ve yöntem için 20 ölçümü ortala; {n} eşli fark oluştur.',f'Fark ortalaması {mean:.3f}; SE={se:.3f}; df={n-1}. Ortalama ± t×SE aralığını kur.',f'İş yükü dönüşümü: 12.000 × {mean:.3f} / 3.600 saat. Bu bir süre eşdeğeridir, otomatik personel azaltma değildir.'],decision=decision,diagnostics={'randomized_sequences':sequence.tolist(),'independent_n':n,'raw_n':len(raw),'minimum_important_difference':important,'ci':[float(ci[0]),float(ci[1])],'mean_difference':mean,'p':test.pvalue},limit='Kontrollü sentetik görev seti, dengeli rastgele AB/BA sırası ve operatörler arası bağımsızlık. Gerçek pilotta taşıma/öğrenme, ürün karışımı, tempo ve tolerans ayrıca değerlendirilir; ölçülen çevrim süresi standart zaman değildir.')
def model_pairs(scenario='default'):
 rng=np.random.default_rng(260802);n=240;y=rng.binomial(1,.16,n);difficulty=rng.normal(0,.7,n);score_a=special.expit((2*y-1)*1.05+difficulty+rng.normal(0,1,n));score_b=special.expit((2*y-1)*1.4+difficulty+rng.normal(0,.9,n));threshold=.5 if scenario=='default' else .35;pa=score_a>=.5;pb=score_b>=threshold;ca=pa==y;cb=pb==y
 table=np.array([[np.sum(ca&cb),np.sum(ca&~cb)],[np.sum(~ca&cb),np.sum(~ca&~cb)]]);test=mcnemar(table,exact=True);b,c=table[0,1],table[1,0];manual=1. if b+c==0 else min(1.,2*stats.binom.cdf(min(b,c),b+c,.5));assert np.isclose(test.pvalue,manual,atol=1e-12)
 def metrics(pred):
  tp=np.sum(pred&(y==1));fp=np.sum(pred&(y==0));fn=np.sum(~pred&(y==1));tn=np.sum(~pred&(y==0));return[tp,fp,fn,tn,np.mean(pred==y),(fp+10*fn)/len(y)*1000]
 ma,mb=metrics(pa),metrics(pb);comparison=pd.DataFrame([['A',.5,*ma],['B',threshold,*mb]],columns=['model','threshold','TP','FP','FN','TN','accuracy','cost_per_1000']);delta=cb.astype(int)-ca.astype(int);boot=np.mean(rng.choice(delta,(1500,n),replace=True),axis=1);ci=np.quantile(boot,[.025,.975]);raw=pd.DataFrame({'record_id':np.arange(1,n+1),'actual_late':y,'score_a':score_a,'score_b':score_b})
 fig,ax=plt.subplots();im=ax.imshow(table,cmap='Blues');ax.set(xticks=[0,1],xticklabels=['B doğru','B yanlış'],yticks=[0,1],yticklabels=['A doğru','A yanlış'],title='Aynı 240 siparişte eşli doğruluk tablosu')
 for i in range(2):
  for j in range(2):ax.text(j,i,str(table[i,j]),ha='center',va='center',fontsize=22,color='#142C49')
 fig2,ax2=plt.subplots();x=np.arange(2);ax2.bar(x-.17,[ma[1],mb[1]],.34,label='Yanlış alarm',color='#235ACB');ax2.bar(x+.17,[ma[2],mb[2]],.34,label='Kaçırma',color='#D5542B');ax2.set(xticks=x,xticklabels=['Model A','Model B'],ylabel='Kayıt sayısı',title='Doğruluk değişimi ile hata yükü ayrı değerlendirilir');ax2.legend()
 decision=f'McNemar p={test.pvalue:.5g}; karar yalnız doğruluğa bırakılmaz. Bu senaryoda A maliyeti {ma[-1]:.1f}, B maliyeti {mb[-1]:.1f} puan/1.000 kayıt. Kaçırma maliyeti 10, yanlış alarm maliyeti 1 varsayımı açıkça korunmalı.'
 return dict(metrics={'A / B doğruluk':f'{ma[4]:.1%} / {mb[4]:.1%}','B−A doğruluk farkı · yüzde puan':100*delta.mean(),'McNemar iki yönlü tam p':test.pvalue,'Uyumsuz çift b+c':int(b+c),'B eşik':threshold},tables=[tbl(comparison,'Hata ve maliyet karşılaştırması'),tbl(pd.DataFrame({'lower':[ci[0]],'upper':[ci[1]]}),'Eşli bootstrap doğruluk farkı aralığı · oran')],figures=[('McNemar yalnız iki uyumsuz hücreyi kullanır; bütün doğruları bağımsız iki grup saymaz.',fig),('Eşik düşürülünce alarm ve kaçırma yükleri farklı değişebilir.',fig2)],frames={'ayni_siparisler':raw},steps=['A ve B aynı siparişler üzerinde değerlendirildi; doğruluk göstergelerini çift olarak eşleştir.',f'A doğru/B yanlış={b}; A yanlış/B doğru={c}. H0 altında {b+c} uyumsuz çiftin yönünü p=.5 binom ile karşılaştır.','İki yönlü tam p=2×küçük kuyruk (en çok 1). Ardından doğal farkı, alt sınıf hatalarını ve önceden seçilmiş maliyeti raporla.'],decision=decision,diagnostics={'table':table.tolist(),'exact_p':test.pvalue,'manual_p':manual,'accuracy_difference':delta.mean(),'bootstrap_ci':ci.tolist(),'n':n},limit='Bağımsız test siparişleri, aynı kayıtlarda iki model ve sabit eşikler. Puanlar sentetik olup kalibre olasılık kanıtı değildir. Final test üzerinde eşiği seçip aynı sonucu tarafsız başarı sayma; eşik senaryoları öğretim içindir.')
def posthoc(scenario='default'):
 rng=np.random.default_rng(260803);names=['A','B','C'];ns=[24,30,36];means=[20,18.5,17.5];scales=[1.5]*3 if scenario=='default' else [1.,2.5,4.];groups=[rng.normal(mu,sd,n) for mu,sd,n in zip(means,scales,ns)];raw=pd.DataFrame([(name,float(v))for name,g in zip(names,groups)for v in g],columns=['method','seconds']);welch=anova_oneway(groups,use_var='unequal');classic=stats.f_oneway(*groups);tukey=pairwise_tukeyhsd(raw.seconds,raw.method,alpha=.05);gh=[]
 for i in range(3):
  for j in range(i+1,3):
   gi,gj=groups[i],groups[j];vi,vj=np.var(gi,ddof=1)/len(gi),np.var(gj,ddof=1)/len(gj);se=np.sqrt(vi+vj);df=(vi+vj)**2/(vi**2/(len(gi)-1)+vj**2/(len(gj)-1));difference=gi.mean()-gj.mean();q=np.sqrt(2)*abs(difference)/se;critical=stats.studentized_range.ppf(.95,3,df)/np.sqrt(2);p=stats.studentized_range.sf(q,3,df);gh.append([names[i]+'−'+names[j],difference,df,p,difference-critical*se,difference+critical*se])
 ghdf=pd.DataFrame(gh,columns=['pair','difference','df','p_adjusted','lower','upper']);summary=raw.groupby('method').seconds.agg(['count','mean','std']).reset_index();fig,ax=plt.subplots();
 for i,g in enumerate(groups):ax.scatter(np.full(len(g),i)+rng.normal(0,.04,len(g)),g,alpha=.5,s=16,color=['#235ACB','#148774','#D5542B'][i])
 ax.set(xticks=range(3),xticklabels=names,ylabel='Paketleme süresi · saniye',title='Ham noktalar: grup ortalamasının yanında yayılımı gör')
 fig2,ax2=plt.subplots();ax2.axvline(0,color='gray',ls='--');ax2.errorbar(ghdf.difference,range(3),xerr=np.vstack([ghdf.difference-ghdf.lower,ghdf.upper-ghdf.difference]),fmt='o',capsize=5,color='#235ACB');ax2.set(yticks=range(3),yticklabels=ghdf.pair,xlabel='Ortalama farkı · saniye',title='Games–Howell eşzamanlı %95 aralıklar')
 tdf=pd.DataFrame(tukey._results_table.data[1:],columns=tukey._results_table.data[0]);assert np.all((ghdf.p_adjusted>=0)&(ghdf.p_adjusted<=1));assert np.all(ghdf.lower<=ghdf.upper)
 decision='Eşit varyanslı öğretim senaryosunda klasik ANOVA ve Tukey tutarlı bir aile oluşturur. Eşit olmayan senaryoda Welch + Games–Howell seç; her çifti düzeltilmemiş t testleriyle tarama.'
 return dict(metrics={'Klasik genel ANOVA p':classic.pvalue,'Welch genel p':float(welch.pvalue),'Bağımsız paket':len(raw),'Varyans senaryosu':'Eşit' if scenario=='default' else 'Eşit değil'},tables=[tbl(summary,'Grup hacmi, merkezi ve yayılımı'),tbl(ghdf,'Games–Howell: A−B yönü'),tbl(tdf,'Tukey: tablodaki meandiff = group2−group1')],figures=[('Her nokta bağımsız bir paket ölçümüdür; renk yöntemdir.',fig),('Sıfırı dışlayan eşzamanlı aralık ilgili çiftin farkını destekler; yönleri tablodaki etikete göre oku.',fig2)],frames={'paket_olcumleri':raw},steps=['Üç bağımsız yöntem grubunda n, ortalama, varyans ve ham dağılımı kontrol et.','Genel H0 bütün ortalamalar eşit. Klasik ANOVA ortak varyans, Welch ayrı varyans hedefiyle kurulur.','Tukey ortak hata varyansına; Games–Howell çiftin ayrı varyansına ve Welch df’sine dayanır. Games–Howell q=√2×|fark|/SE; aile büyüklüğü k=3.'],decision=decision,diagnostics={'classic_p':classic.pvalue,'welch_p':float(welch.pvalue),'gh':ghdf.to_dict('records'),'ns':ns,'stds':[np.std(g,ddof=1)for g in groups]},limit='Sentetik bağımsız normal paket ölçümleri; yöntemler uygun paketlere rastgele atanmış varsayılır. Gerçek çalışmada operatör/vardiya ve sıra etkisi blok gerektirebilir. Varyans ailesi yalnız Levene p’sine göre otomatik seçilmez. İstatistiksel fark işte en iyi yöntem demek değildir.')
def demand(scenario='default'):
 rng=np.random.default_rng(260804);n=266;dates=pd.date_range('2026-01-01',periods=n,freq='D');time=np.arange(n);weekly=np.array([8,15,20,10,0,-25,-30]);noise=np.zeros(n)
 for t in range(1,n):noise[t]=.4*noise[t-1]+rng.normal(0,5)
 y=150+.12*time+weekly[dates.dayofweek]+noise
 if scenario!='default':y[238:]+=25
 series=pd.Series(np.round(y),index=dates,name='orders');train,val,test=series.iloc[:210],series.iloc[210:238],series.iloc[238:];candidates=[((1,0,0),(0,1,1,7)),((0,1,1),(0,1,1,7))];rows=[];fits=[]
 for order,season in candidates:
  fit=SARIMAX(train,order=order,seasonal_order=season,trend='c',enforce_stationarity=True,enforce_invertibility=True).fit(disp=False,maxiter=300);pred=fit.get_forecast(len(val)).predicted_mean;mae=np.mean(abs(val-pred));converged=bool(fit.mle_retvals.get('converged',False));rows.append([str(order),str(season),float(fit.aic),float(mae),converged]);fits.append(fit)
 eligible=[i for i in range(len(fits))if rows[i][-1]]
 if not eligible:raise RuntimeError('Adayların hiçbiri yakınsamadı; model başarı diye sunulamaz.')
 best=min(eligible,key=lambda i:rows[i][3]);order,season=candidates[best];history=pd.concat([train,val]);final=SARIMAX(history,order=order,seasonal_order=season,trend='c',enforce_stationarity=True,enforce_invertibility=True).fit(disp=False,maxiter=300)
 if not final.mle_retvals.get('converged',False):raise RuntimeError('Final model yakınsamadı.')
 forecast=final.get_forecast(len(test));pred=forecast.predicted_mean;ci=forecast.conf_int(alpha=.05);# frozen-origin multi-step seasonal naive repeats the final observed week, no actual test values used
 baseline=np.tile(history.iloc[-7:].values,4);mae=lambda p:float(np.mean(abs(test.values-np.asarray(p))));rmse=lambda p:float(np.sqrt(np.mean((test.values-np.asarray(p))**2)));coverage=float(np.mean((test.values>=ci.iloc[:,0].values)&(test.values<=ci.iloc[:,1].values)));errors=final.resid.iloc[21:];lb=acorr_ljungbox(errors,lags=[14],model_df=2,return_df=True).iloc[0].lb_pvalue
 raw=pd.DataFrame({'date':dates.strftime('%Y-%m-%d'),'orders':series.values,'partition':['train']*210+['validation']*28+['final_test']*28});validation=pd.DataFrame(rows,columns=['order','seasonal_order','train_AIC','validation_MAE','converged']);evaluation=pd.DataFrame([['Mevsimsel naif',mae(baseline),rmse(baseline)],['Seçilmiş SARIMA',mae(pred),rmse(pred)]],columns=['model','test_MAE','test_RMSE']);predframe=pd.DataFrame({'date':test.index.strftime('%Y-%m-%d'),'actual':test.values,'seasonal_naive':baseline,'sarima':pred.values,'lower95':ci.iloc[:,0].values,'upper95':ci.iloc[:,1].values})
 assert list(pred.index)==list(test.index) and history.index.max()<test.index.min();assert len(test)==28
 fig,ax=plt.subplots(figsize=(9.5,4.3));ax.plot(series,label='Gerçek talep',color='#61738D');ax.axvline(val.index[0],color='#D99A28',ls='--',label='Validasyon başlangıcı');ax.axvline(test.index[0],color='#D5542B',ls='--',label='Final test başlangıcı');ax.set(ylabel='Sipariş · adet',title='210 gün eğitim → 28 gün seçim → 28 gün final test');ax.legend(fontsize=8);fig.autofmt_xdate()
 fig2,ax2=plt.subplots(figsize=(9.5,4.3));ax2.plot(test.index,test.values,'o-',label='Gerçek',color='#142C49');ax2.plot(test.index,pred.values,label='SARIMA',color='#235ACB');ax2.plot(test.index,baseline,label='Mevsimsel naif',color='#D5542B');ax2.fill_between(test.index,ci.iloc[:,0].values,ci.iloc[:,1].values,color='#235ACB',alpha=.12,label='Model %95 tahmin aralığı');ax2.set(ylabel='Sipariş · adet',title='Tek kesimden 28 günlük ileri tahmin');ax2.legend(fontsize=8);fig2.autofmt_xdate()
 decision=f'Final test MAE: SARIMA {mae(pred):.2f}, taban {mae(baseline):.2f} adet. '+('Seçilmiş model bu testte daha düşük hata verdi; sonraki dönemi garanti etmez.'if mae(pred)<mae(baseline)else'Tabanı geçemedi; daha karmaşık olduğu için bu modeli seçme.')
 return dict(metrics={'Eğitim / seçim / test günü':'210 / 28 / 28','SARIMA test MAE':mae(pred),'Taban test MAE':mae(baseline),'Finalde gözlenen %95 kapsam':coverage,'Artık Ljung–Box p · lag14':float(lb)},tables=[tbl(validation,'Aday seçimi yalnız validasyonda'),tbl(evaluation,'Aynı final döneminde karşılaştırma')],figures=[('Kesim tarihleri modelden önce belirlenir; final test model seçmek için geri kullanılmaz.',fig),('Tahminler aynı kesimden üretilir; naif taban da gelecekteki gerçekleşenleri kullanmaz.',fig2)],frames={'gunluk_talep':raw,'final_tahminler':predframe},steps=['İlk 210 günü eğitim, sonraki 28 günü model seçimi, son 28 günü final test olarak ayır.','Önceden seçilmiş iki adayın validasyon MAE’sini ve yakınsamasını kontrol et; seçilen aileyi ilk 238 günde yeniden eğit.','Aynı kesimden 28 adım tahmin et. Mevsimsel naif taban son gözlenen haftayı tekrar eder; MAE/RMSE ve tahmin aralığı kapsamını aynı tarihlerde kıyasla.'],decision=decision,diagnostics={'train_end':str(train.index[-1].date()),'selection_end':str(val.index[-1].date()),'test_start':str(test.index[0].date()),'test_n':len(test),'selected_order':list(order),'selected_season':list(season),'validation_rows':rows,'final_converged':True,'mae_sarima':mae(pred),'mae_baseline':mae(baseline),'coverage':coverage,'ljung_box_p':float(lb)},limit='Sentetik tek günlük seri; sınırlı iki adaylı öğretim araması. Normal hata tabanlı model aralıkları kayma altında garanti sağlamaz. Kırılma senaryosunda final dönemdeki yeni seviye eğitime verilmez. Gerçek operasyon ayrıca takvim, kampanya, kesintiler ve maliyet temelli ufuk ister.')
def gage(scenario='default'):
 rng=np.random.default_rng(260805);parts,operators,repeats=12,3,3;truth=rng.normal(120,1.8,parts);offset=np.array([-.2,.05,.15]);interaction=rng.normal(0,.07,(parts,operators));sigma=.15 if scenario=='default' else .65;rows=[]
 for i in range(parts):
  for j in range(operators):
   for r in range(repeats):rows.append([str(i+1),['A','B','C'][j],r+1,truth[i]+offset[j]+interaction[i,j]+rng.normal(0,sigma)])
 raw=pd.DataFrame(rows,columns=['part','operator','repeat','millimeters']);raw=raw.iloc[rng.permutation(len(raw))].reset_index(drop=True);raw['measurement_order']=np.arange(1,len(raw)+1);grand=raw.millimeters.mean();pm=raw.groupby('part').millimeters.mean();om=raw.groupby('operator').millimeters.mean();cm=raw.groupby(['part','operator']).millimeters.mean();ssp=operators*repeats*np.sum((pm-grand)**2);sso=parts*repeats*np.sum((om-grand)**2);ssi=repeats*sum((cm.loc[i,j]-pm.loc[i]-om.loc[j]+grand)**2 for i,j in cm.index);sse=sum((row.millimeters-cm.loc[row.part,row.operator])**2 for row in raw.itertuples());dfs=np.array([parts-1,operators-1,(parts-1)*(operators-1),parts*operators*(repeats-1)]);ss=np.array([ssp,sso,ssi,sse]);ms=ss/dfs
 # Independent reference through balanced two-factor OLS ANOVA.
 ref=sm.stats.anova_lm(smf.ols('millimeters ~ C(part)*C(operator)',raw).fit(),typ=2);assert np.allclose(ss,ref['sum_sq'].values,rtol=1e-8,atol=1e-8)
 ve=ms[3];vpo=max(0,(ms[2]-ms[3])/repeats);vo=max(0,(ms[1]-ms[2])/(parts*repeats));vp=max(0,(ms[0]-ms[2])/(operators*repeats));rr=ve+vpo+vo;total=rr+vp;sdrr=np.sqrt(rr);study=100*np.sqrt(rr/total);contrib=100*rr/total;tolerance=10.;ptol=100*6*sdrr/tolerance;ndc=int(np.floor(1.41*np.sqrt(vp)/sdrr));table=pd.DataFrame({'source':['Parça','Operatör','Parça×operatör','Tekrar hatası'],'SS':ss,'df':dfs,'MS':ms});comp=pd.DataFrame({'component':['Repeatability','Operator','Interaction','Part'],'variance':[ve,vo,vpo,vp],'SD':np.sqrt([ve,vo,vpo,vp])});reference_thresholds={'study_percent':20,'tolerance_percent':15};decision='Bu eğitim vakasının önceden seçilmiş iç ölçütleri (%study≤20 ve %tolerans≤15) '+('sağlandı.'if study<=20 and ptol<=15 else'sağlanmadı; cihaz/operatör/uygulama kaynağını iyileştirmeden küçük süreç farklarına güvenme.')
 fig,ax=plt.subplots();means=raw.groupby(['part','operator']).millimeters.mean().unstack('operator').reindex([str(i+1)for i in range(parts)])
 for name in means.columns:ax.plot(range(1,parts+1),means[name],'o-',label='Operatör '+name)
 ax.set(xlabel='Parça',ylabel='Tekrar ortalaması · mm',title='Aynı parçalar, üç operatör, üç tekrar');ax.legend()
 fig2,ax2=plt.subplots();ax2.bar(comp.component,comp.variance,color=['#235ACB','#D5542B','#BE8D28','#148774']);ax2.set(ylabel='Varyans · mm²',title='Varyans bileşenleri · SD yüzdesiyle karıştırma');fig2.autofmt_xdate()
 return dict(metrics={'Parça × operatör × tekrar':'12 × 3 × 3','Gage R&R SD · mm':sdrr,'% study variation':study,'% variance contribution':contrib,'% tolerance · genişlik 10 mm':ptol,'ndc · örnek tahmin':ndc},tables=[tbl(table,'Dengeli çapraz ANOVA'),tbl(comp,'Negatif moment tahminleri 0’a kırpılmış bileşenler')],figures=[('Parça etkisini operatör ve tekrar katkısından ayırmak için aynı parçalar çapraz ölçülür.',fig),('Toplam varyans bileşenlerinin toplama kuralı SD’lere doğrudan uygulanmaz.',fig2)],frames={'capraz_olcumler':raw},steps=['Temsil edici 12 parça, üç operatör, her hücrede üç tekrar; ölçüm sırası rastgele.','Dengeli iki faktörlü ANOVA’da parça, operatör, etkileşim ve hücre içi hatanın SS/df/MS değerlerini ayır.','σ²e=MSerror; σ²etkileşim=(MSint−MSerror)/r; σ²operatör=(MSop−MSint)/(p×r); σ²parça=(MSpart−MSint)/(o×r). Negatif moment tahminleri sıfıra kırpılır.','RR varyansı tekrar+operatör+etkileşimdir. %study SD oranıdır; %contribution varyans oranıdır. Tolerans yüzdesi 6×SD_RR/tolerans genişliğidir.'],decision=decision,diagnostics={'ss':ss.tolist(),'ols_ss':ref['sum_sq'].values.tolist(),'variances':{'repeat':ve,'operator':vo,'interaction':vpo,'part':vp},'study_percent':study,'contribution_percent':contrib,'tolerance_percent':ptol,'ndc':ndc,'n':len(raw),'thresholds':reference_thresholds},limit='Dengeli, çapraz, rastgele etkili ANOVA moment yaklaşımı; parça ve operatör temsili, sabit varyans ve kararlılık varsayımları gerekir. İç eşikler öğretim senaryosudur, evrensel standart değildir. Bileşen güven aralıkları/negatif tahmin belirsizliği burada hesaplanmaz; etkileşim havuzlanmaz.')
def control(scenario='default'):
 rng=np.random.default_rng(260806);m,n=40,5;raw=rng.normal(20,1,(m,n));raw[35:]+=3 if scenario=='default' else 0;phase=np.array(['reference']*30+['monitor']*10);mean=raw.mean(axis=1);ranges=np.ptp(raw,axis=1);xbar=mean[:30].mean();rbar=ranges[:30].mean();xl,xu=xbar-.577*rbar,xbar+.577*rbar;ru=2.114*rbar;range_flags=np.where(ranges>ru)[0]+1;mean_flags=np.where((mean<xl)|(mean>xu))[0]+1
 sizes=rng.integers(220,501,m);d=[];defectives=[]
 for i,N in enumerate(sizes):
  events=rng.poisson(.08 if i<35 or scenario!='default' else .22,int(N));d.append(events.sum());defectives.append(np.sum(events>0))
 d=np.array(d);defectives=np.array(defectives);p=defectives/sizes;u=d/sizes;pbar=defectives[:30].sum()/sizes[:30].sum();ubar=d[:30].sum()/sizes[:30].sum();pl=np.maximum(0,pbar-3*np.sqrt(pbar*(1-pbar)/sizes));pu=np.minimum(1,pbar+3*np.sqrt(pbar*(1-pbar)/sizes));ul=np.maximum(0,ubar-3*np.sqrt(ubar/sizes));uu=ubar+3*np.sqrt(ubar/sizes);pf=np.where((p<pl)|(p>pu))[0]+1;uf=np.where((u<ul)|(u>uu))[0]+1
 continuous=pd.DataFrame({'subgroup':np.repeat(np.arange(1,m+1),n),'phase':np.repeat(phase,n),'within_group':np.tile(np.arange(1,n+1),m),'seconds':raw.ravel()});counts=pd.DataFrame({'day':np.arange(1,m+1),'phase':phase,'inspected':sizes,'defective_units':defectives,'total_defects':d});assert np.all(defectives<=sizes)and np.all(d>=defectives);limits=pd.DataFrame({'day':np.arange(1,m+1),'p':p,'p_LCL':pl,'p_UCL':pu,'u':u,'u_LCL':ul,'u_UCL':uu});days=np.arange(1,m+1)
 fig,axes=plt.subplots(2,1,figsize=(9.2,6.2),sharex=True)
 for ax,vals,center,low,high,label in [(axes[0],mean,xbar,np.full(m,xl),np.full(m,xu),'Alt grup ortalaması · sn'),(axes[1],ranges,rbar,np.zeros(m),np.full(m,ru),'Alt grup aralığı · sn')]:
  ax.plot(days,vals,'o-',ms=3,color='#235ACB');ax.axhline(center,color='#148774',label='Referans merkez');ax.plot(days,low,'--',color='#D5542B');ax.plot(days,high,'--',color='#D5542B',label='Kontrol sınırı');ax.axvline(30.5,color='gray',ls=':');ax.set_ylabel(label)
 axes[0].set_title('X̄–R: önce R, sonra X̄; ilk 30 alt grubun sınırları donduruldu');axes[0].legend(fontsize=8);axes[1].set_xlabel('Alt grup · her birinde 5 ardışık ölçüm');fig.tight_layout()
 fig2,axes2=plt.subplots(2,1,figsize=(9.2,6.2),sharex=True)
 for ax,vals,center,low,high,label in [(axes2[0],p,pbar,pl,pu,'En az bir kusurlu birim payı p'),(axes2[1],u,ubar,ul,uu,'Birim başına toplam kusur u')]:
  ax.plot(days,vals,'o-',ms=3,color='#235ACB');ax.axhline(center,color='#148774');ax.plot(days,low,'--',color='#D5542B');ax.plot(days,high,'--',color='#D5542B');ax.axvline(30.5,color='gray',ls=':');ax.set_ylabel(label)
 axes2[0].set_title('Değişen incelenen miktarda p ve u sınırları da değişir');axes2[1].set_xlabel('Gün');fig2.tight_layout()
 signals=pd.DataFrame({'chart':['R','Xbar','p','u'],'reference_flags':[str([int(x)for x in f if x<=30])for f in [range_flags,mean_flags,pf,uf]],'monitor_flags':[str([int(x)for x in f if x>30])for f in [range_flags,mean_flags,pf,uf]]});reference_any=any(np.any(f<=30)for f in [range_flags,mean_flags,pf,uf]);decision=('Referans döneminde sınır dışı noktalar var; bu sınırları kararlı süreç kanıtı gibi kullanma, önce referansı araştır. 'if reference_any else'Referans döneminde bu tek kurala göre sınır dışı sinyal yok. ')+('İzlemede sinyaller var: gün/alt grup kaynağını araştır; tolerans veya performans hedefiyle karıştırma.'if any(np.any(f>30)for f in [range_flags,mean_flags,pf,uf])else'İzlemede bu tek kurala göre sinyal yok; bu, bütün özel nedenlerin dışlandığı anlamına gelmez.')
 return dict(metrics={'Referans / izleme':'30 / 10 dönem','X̄ merkez · sn':xbar,'R ortalaması · sn':rbar,'p referans oranı':pbar,'u referans oranı':ubar,'İncelenen günlük miktar':f'{sizes.min()}–{sizes.max()}'},tables=[tbl(signals,'Yalnız üç-sigma sınır dışı sinyalleri'),tbl(pd.DataFrame({'Xbar_LCL':[xl],'Xbar_UCL':[xu],'R_UCL':[ru]}),'Referanstan dondurulmuş sürekli ölçüm sınırları')],figures=[('R değişkenliği denetlenmeden ortalama grafiği tek başına yorumlanmaz. Sınırlar yeni ölçümler geldikçe yeniden fit edilmedi.',fig),('p kusurlu birim payı; u toplam kusur/birim. Aynı birimde birden fazla kusur olabilir.',fig2)],frames={'sure_alt_gruplari':continuous,'sayimlar':counts,'p_u_sinirlari':limits},steps=['Önce veri türü: n=5 rasyonel alt grupta sürekli süre → X̄–R; birimin uygun/uygunsuzluğu → p; birim başına toplam kusur → u.','İlk 30 dönemde X̄̄, R̄, p̄=Σkusurlu/Σn ve ū=Σkusur/Σn tahmin et. İzleme için bu referansı dondur.','n=5 için X̄ sınırları X̄̄±0,577R̄; R sınırları [0,2,114R̄]. p/u sınırları o günün n değerini kullanır.','Önce referans sinyalini, ardından izleme sinyalini araştır. Sabit n için np, sabit maruziyette c düşünülebilir; değişken n durumunda ham sayıyı tek sabit sınırla kıyaslama.'],decision=decision,diagnostics={'Xbar_limits':[float(xl),float(xu)],'R_upper':float(ru),'pbar':float(pbar),'ubar':float(ubar),'mean_flags':mean_flags.tolist(),'range_flags':range_flags.tolist(),'p_flags':pf.tolist(),'u_flags':uf.tolist(),'reference_any_signal':reference_any,'reference_n':30},limit='Bağımsız ve karşılaştırılabilir rasyonel alt gruplar; sürekli model için uygun dağılım ve n=5 sabitleri. p için binom, u için Poisson yaklaşımı; aşırı saçılım/kümelenme ayrıca incelenir. Yalnız üç-sigma sınır dışı kuralı; bütün koşu kuralları, X̄–S veya risk ayarlı grafikler uygulanmaz.')
def classifier(scenario='default'):
 from sklearn.pipeline import make_pipeline
 from sklearn.preprocessing import StandardScaler
 from sklearn.linear_model import LogisticRegression
 from sklearn.ensemble import RandomForestClassifier
 from sklearn.metrics import brier_score_loss,roc_auc_score,average_precision_score,log_loss
 from sklearn.calibration import calibration_curve
 rng=np.random.default_rng(260807);day=np.repeat(np.arange(1,85),14);N=len(day);items=rng.poisson(6,N)+1;queue=np.maximum(1,rng.normal(35+.2*day,15));promise=rng.choice([24,48,72],N);night=rng.binomial(1,.3,N);p=special.expit(-3.3+.08*items+.035*queue-.025*promise+.45*night+.7*(items>10)*(queue>60));y=rng.binomial(1,p);final_duration=promise+np.where(y==1,rng.gamma(2,4,N),-rng.uniform(.5,10,N));raw=pd.DataFrame({'order_id':np.arange(1,N+1),'day':day,'items':items,'queue_at_open':queue,'promise_hours':promise,'night':night,'actual_late':y,'final_duration_hours':final_duration});features=['items','queue_at_open','promise_hours','night']+(['final_duration_hours']if scenario=='leaky'else[]);tr=day<=56;va=(day>56)&(day<=70);te=day>70;models=[('Lojistik',make_pipeline(StandardScaler(),LogisticRegression(C=1,max_iter=1000,random_state=7))),('Orman',RandomForestClassifier(n_estimators=80,max_depth=5,min_samples_leaf=8,random_state=7,n_jobs=1))];rows=[]
 for name,m in models:
  m.fit(raw.loc[tr,features],y[tr]);pv=m.predict_proba(raw.loc[va,features])[:,1];rows.append([name,brier_score_loss(y[va],pv),average_precision_score(y[va],pv)])
 selected=int(np.argmin([r[1]for r in rows]));name,model=models[selected];pv=model.predict_proba(raw.loc[va,features])[:,1];thresholds=np.arange(.1,.91,.05);cost=lambda actual,pred:float(np.mean((pred==1)&(actual==0))+10*np.mean((pred==0)&(actual==1)));costs=[cost(y[va],pv>=t)for t in thresholds];threshold=float(thresholds[np.argmin(costs)]);model.fit(raw.loc[~te,features],y[~te]);pt=model.predict_proba(raw.loc[te,features])[:,1];decision=pt>=threshold;actual=y[te];TP=int(np.sum(decision&(actual==1)));FP=int(np.sum(decision&(actual==0)));FN=int(np.sum(~decision&(actual==1)));TN=int(np.sum(~decision&(actual==0)));baseline=np.full(np.sum(te),y[tr].mean());validation=pd.DataFrame(rows,columns=['model','validation_Brier','validation_AP']);scores=pd.DataFrame([['Sabit eğitim oranı',brier_score_loss(actual,baseline),roc_auc_score(actual,baseline),average_precision_score(actual,baseline)],['Seçilen model',brier_score_loss(actual,pt),roc_auc_score(actual,pt),average_precision_score(actual,pt)]],columns=['model','test_Brier','test_ROC_AUC','test_AP']);raw['partition']=np.where(tr,'train',np.where(va,'validation','final_test'));prediction=raw.loc[te,['order_id','actual_late']].copy();prediction['score']=pt;prediction['decision']=decision.astype(int)
 fig,ax=plt.subplots();obs,mean=calibration_curve(actual,pt,n_bins=5,strategy='quantile');ax.plot(mean,obs,'o-',color='#235ACB',label='Final test');ax.plot([0,1],[0,1],'--',color='gray',label='İdeal çizgi');ax.set(xlabel='Bin içindeki ortalama tahmin',ylabel='Gözlenen gecikme payı',title='Kalibrasyon kontrolü · finalden kalibratör öğrenilmedi');ax.legend()
 fig2,ax2=plt.subplots();ax2.bar(['TP','FP','FN','TN'],[TP,FP,FN,TN],color=['#148774','#D5542B','#BE8D28','#235ACB']);ax2.set(ylabel='Sipariş sayısı',title=f'Validasyondan seçilmiş sabit eşik {threshold:.2f}')
 result_text=('Bu senaryoda final süre özelliği teslimden sonra oluşuyor. Skor yüksek olsa bile tahmin anında kullanılamaz; devreye alma önerisi olarak sunulamaz.'if scenario=='leaky'else f'{name} modeli ve {threshold:.2f} eşik seçim döneminden geldi. Final testte Brier={brier_score_loss(actual,pt):.4f}; 1.000 siparişte maliyet={1000*cost(actual,decision):.1f} puan. Operasyon kapasitesi ve yeni dönem izleme planı olmadan otomatik devreye alma kararı verme.')
 assert raw.loc[tr,'day'].max()<raw.loc[va,'day'].min()and raw.loc[va,'day'].max()<raw.loc[te,'day'].min();assert set(np.unique(actual))=={0,1}
 return dict(metrics={'Eğitim / seçim / final n':f'{tr.sum()} / {va.sum()} / {te.sum()}','Seçilmiş model':name,'Sabit karar eşiği':threshold,'Final Brier':brier_score_loss(actual,pt),'Final ROC-AUC':roc_auc_score(actual,pt),'Final AP':average_precision_score(actual,pt),'Kaçırma / yanlış alarm':f'{FN} / {FP}','Özellik erişimi':'Uygun değil: teslim sonrası bilgi'if scenario=='leaky'else'Tahmin anında bilinen özellikler'},tables=[tbl(validation,'Aile seçimi yalnız validasyon Brier ile'),tbl(scores,'Final testte taban karşılaştırması')],figures=[('Kalibrasyon grafiği bin ortalamalarıdır; küçük test örneklemindeki oynaklığı unutma.',fig),('Doğruluk yanında iki hata türünü ve maliyetini ayrı göster.',fig2)],frames={'siparis_model_verisi':raw,'bagimsiz_final_sonuclari':prediction},steps=['Gün 1–56 eğitim, 57–70 seçim, 71–84 final test. Özelliğin sipariş açılırken bilinip bilinmediğini denetle.','Ölçekleyici lojistik pipeline içinde yalnız eğitimde öğrenilir. İki önceden seçilmiş adayın ailesi validasyon Brier ile seçilir.','Eşik yalnız validasyonda FP maliyeti 1, FN maliyeti 10 ile seçilir. Aile/eşik sabitken model ilk 70 günde yeniden eğitilip finalde bir kez değerlendirilir.','Brier, ROC-AUC, AP, kalibrasyon ve karar tablosu farklı sorulara cevap verir. Sızıntı senaryosundaki iyi skoru kullanım kanıtı sayma.'],decision=result_text,diagnostics={'n_train':int(tr.sum()),'n_val':int(va.sum()),'n_test':int(te.sum()),'train_max_day':int(day[tr].max()),'val_min_day':int(day[va].min()),'val_max_day':int(day[va].max()),'test_min_day':int(day[te].min()),'features':features,'selected':name,'threshold':threshold,'brier':brier_score_loss(actual,pt),'auc':roc_auc_score(actual,pt),'AP':average_precision_score(actual,pt),'TP':TP,'FP':FP,'FN':FN,'TN':TN,'leaky':scenario=='leaky'},limit='Sentetik, tek depo, günlük sıralı siparişler; hedef gelecekteki aynı kullanım ortamıdır. Yeni müşteri/çok depo genellemesi ayrıca test ister. Hata maliyetleri öğretim varsayımıdır. Kalibrasyon yalnız incelenir; ayrı kalibratör eğitilmez. Senaryo karşılaştırmaları final testte yeni seçim yapmak için kullanılmaz.')

